python - <<'PY'
import pandas as pd
from pymatgen.core import Structure
from pymatgen.analysis.structure_matcher import StructureMatcher
p=pd.read_csv('nlo_pool.csv'); ids=p.candidate_id.tolist(); ss=[Structure.from_str(x,fmt='poscar') for x in p.poscar]
sm=StructureMatcher(ltol=.3,stol=.5,angle_tol=5,primitive_cell=False,scale=True,attempt_supercell=True)
for formula,g in p.groupby('formula'):
 if len(g)>1:
  z=[]
  for ai,a in enumerate(g.index):
   for b in g.index[ai+1:]:
    if sm.fit(ss[a],ss[b]):
     try:r=sm.get_rms_dist(ss[a],ss[b])
     except:r=None
     z.append((ids[a],ids[b],r))
  print(formula,z)
PY

