python - <<'PY'
import pandas as pd, numpy as np
from pymatgen.core import Structure
p=pd.read_csv('nlo_pool.csv').set_index('candidate_id')
for cid,e,cut in [('c007','As',2.8),('c061','S',2.3),('c089','Se',2.6),('c064','S',2.3)]:
 s=Structure.from_str(p.loc[cid].poscar,fmt='poscar'); print('\n',cid)
 for i,x in enumerate(s):
  if x.specie.symbol==e:
   ns=[n for n in s.get_neighbors(x,cut) if n.specie.symbol==e]
   if ns:
    print(i,[round(n.nn_distance,2) for n in ns], end=' ')
    if len(ns)>=2:
     u=[(n.coords-x.coords)/n.nn_distance for n in ns]
     print('angle',round(np.degrees(np.arccos(np.clip(u[0]@u[1],-1,1))),1))
    else:print()
PY

